WITH agg AS ( SELECT cd.cd_education_status AS education, cd.cd_gender AS gender, hd.hd_income_band_sk AS income_band, COUNT(*) AS cust_cnt, SUM(cd.cd_purchase_estimate) AS total_purchase_est, AVG(cd.cd_dep_employed_count) AS avg_emp_deps, AVG(hd.hd_vehicle_count) AS avg_vehicles, SUM(cd.cd_dep_college_count) AS total_college_deps FROM customer_demographics cd JOIN household_demographics hd ON cd.cd_demo_sk = hd.hd_demo_sk WHERE cd.cd_credit_rating = 'Good' AND cd.cd_marital_status = 'M' AND hd.hd_buy_potential = 'High' AND cd.cd_education_status IN ('College', '4 yr Degree') GROUP BY cd.cd_education_status, cd.cd_gender, hd.hd_income_band_sk HAVING COUNT(*) >= 5 ) SELECT education, gender, income_band, cust_cnt, total_purchase_est, avg_emp_deps, avg_vehicles, total_college_deps, RANK() OVER (ORDER BY total_purchase_est DESC) AS purchase_rank FROM agg ORDER BY purchase_rank LIMIT 50
